"""Shared wire types and bounded metadata for the offline campaign tools."""
import base64
import binascii
import ipaddress
import json
import re

DOC = ipaddress.IPv6Network('2001:db8::/32')
ID = re.compile(r'[A-Za-z0-9_-]{1,24}\Z')
COLUMNS = ('type','id','revision','published','op','lease','event','probe',
           'target','responder','result','service','attempt','payload')
MAX_TIME = 10**12
MAX_REVISION = 10**9
MAX_ATTEMPT = 10**6
MAX_FIELD = 131072
MAX_RECORDS = 200000
MAX_CHUNKS = 1024
MAX_DECODED = 32*1024**2
MAX_PLAIN = 128*1024**2
MAX_PAYLOAD = 65536
MAX_TARGETS = 65536
KINDS = ('tcp','adb','sync')


class Invalid(ValueError):
    """The root metadata or the JSON envelope is unusable."""


class CaptureError(ValueError):
    """A capture transport, encoding, header or bound is unusable."""


def need(condition):
    if not condition:
        raise Invalid('invalid metadata')


def ident(value):
    return isinstance(value,str) and ID.fullmatch(value) is not None


def integer(value,low=0,high=MAX_TIME):
    return type(value) is int and low <= value <= high


def fields(value,names):
    return type(value) is dict and set(value)==set(names.split())


def address(text):
    need(isinstance(text,str) and len(text)<=64 and '%' not in text
         and not any(c.isspace() for c in text))
    try:
        value=ipaddress.IPv6Address(text)
    except ValueError:
        raise Invalid('invalid IPv6 address') from None
    need(value in DOC)
    return int(value)


